const dormantAfterDays = 14

func parseRowTime(s string) (time.Time, bool) {
	for _, layout := range []string{
		"2006-01-02 15:04:05.999999-07", "2006-01-02 15:04:05.999999-07:00",
		"2006-01-02 15:04:05-07", time.RFC3339Nano, time.RFC3339,
	} {
		if t, err := time.Parse(layout, strings.TrimSpace(s)); err == nil { return t, true }
	}
	return time.Time{}, false   // caller treats as ACTIVE: fail toward alarming
}

